// mem.cpp — Windows process memory reader
// Attach to a process by name, read a 64-bit value at a module-relative offset,
// and resolve a 3-level pointer chain.
//
// C++17 | MSVC or MinGW-w64 | x64 target
//
// Build (MSVC):   cl /std:c++17 /O2 mem.cpp /link psapi.lib
// Build (MinGW):  g++ -std=c++17 -O2 mem.cpp -lpsapi -o mem.exe

#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>

#include <array>
#include <cstdint>
#include <cstdio>
#include <stdexcept>
#include <string>

#pragma comment(lib, "psapi.lib")

// ─── process helpers ─────────────────────────────────────────────────────────

// Returns the PID of the first process whose image name matches `name`
// (case-insensitive).  Throws if no match is found.
static DWORD get_process_id(const wchar_t* name)
{
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE)
        throw std::runtime_error("CreateToolhelp32Snapshot failed: " +
                                 std::to_string(GetLastError()));

    PROCESSENTRY32W entry{};
    entry.dwSize = sizeof(entry);

    for (BOOL ok = Process32FirstW(snap, &entry); ok;
         ok      = Process32NextW(snap, &entry))
    {
        if (_wcsicmp(entry.szExeFile, name) == 0)
        {
            const DWORD pid = entry.th32ProcessID;
            CloseHandle(snap);
            return pid;
        }
    }

    CloseHandle(snap);
    throw std::runtime_error("process not found");
}

// Opens the target process with the rights needed for VM reads.
// Throws on failure.
static HANDLE open_process(DWORD pid)
{
    HANDLE h = OpenProcess(
        PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h)
        throw std::runtime_error("OpenProcess failed: " +
                                 std::to_string(GetLastError()));
    return h;
}

// ─── module helpers ───────────────────────────────────────────────────────────

// Returns the load address of `mod_name` inside `proc`.
// Pass nullptr or L"" to get the base of the first module (the main executable).
static uintptr_t get_module_base(HANDLE proc, const wchar_t* mod_name)
{
    HMODULE mods[1024]{};
    DWORD   needed = 0;

    if (!EnumProcessModulesEx(proc, mods, sizeof(mods), &needed,
                              LIST_MODULES_ALL))
        throw std::runtime_error("EnumProcessModulesEx failed: " +
                                 std::to_string(GetLastError()));

    const DWORD count = needed / static_cast<DWORD>(sizeof(HMODULE));

    for (DWORD i = 0; i < count; ++i)
    {
        wchar_t path[MAX_PATH]{};
        if (!GetModuleFileNameExW(proc, mods[i], path, MAX_PATH))
            continue;

        // Compare only the filename component so callers can pass "engine.dll"
        // rather than a full path.
        const wchar_t* base = wcsrchr(path, L'\\');
        base = base ? base + 1 : path;

        if (!mod_name || mod_name[0] == L'\0' ||
            _wcsicmp(base, mod_name) == 0)
        {
            return reinterpret_cast<uintptr_t>(mods[i]);
        }
    }

    throw std::runtime_error("module not found");
}

// ─── memory primitive ────────────────────────────────────────────────────────

// Reads sizeof(T) bytes from `addr` in `proc`.
// Throws std::runtime_error on a partial or failed read.
template <typename T>
static T rpm(HANDLE proc, uintptr_t addr)
{
    T      value{};
    SIZE_T bytes_read = 0;

    const BOOL ok = ReadProcessMemory(
        proc, reinterpret_cast<LPCVOID>(addr),
        &value, sizeof(T), &bytes_read);

    if (!ok || bytes_read != sizeof(T))
    {
        char hex[24];
        snprintf(hex, sizeof(hex), "%llx",
                 static_cast<unsigned long long>(addr));
        throw std::runtime_error(
            std::string("ReadProcessMemory failed at 0x") + hex +
            " (" + std::to_string(GetLastError()) + ")");
    }

    return value;
}

// ─── high-level reads ────────────────────────────────────────────────────────

// Reads a uint64_t directly at module_base + module_offset.
// No pointer indirection — a flat absolute read at a known offset.
static uint64_t read_at_module_offset(HANDLE   proc,
                                      uintptr_t module_base,
                                      uintptr_t module_offset)
{
    return rpm<uint64_t>(proc, module_base + module_offset);
}

// Resolves a 3-level pointer chain and returns the final uint64_t.
//
//   chain[0]  offset from module_base  → address of ptr0
//   chain[1]  offset added to ptr0     → address of ptr1
//   chain[2]  offset added to ptr1     → address of final value
//
// Equivalent C (in-process):
//   *(uint64_t*)( (*(uintptr_t*)( (*(uintptr_t*)(base + chain[0])) + chain[1] )) + chain[2] )
static uint64_t resolve_ptr_chain(HANDLE   proc,
                                  uintptr_t module_base,
                                  const std::array<uintptr_t, 3>& chain)
{
    // Level 1: read pointer at base + chain[0]
    uintptr_t ptr = rpm<uintptr_t>(proc, module_base + chain[0]);

    // Level 2: read pointer at ptr + chain[1]
    ptr = rpm<uintptr_t>(proc, ptr + chain[1]);

    // Level 3: read final 64-bit value at ptr + chain[2]
    return rpm<uint64_t>(proc, ptr + chain[2]);
}

// ─── entry point ─────────────────────────────────────────────────────────────

int main()
{
    try
    {
        // ── edit these for your target ────────────────────────────────────────
        constexpr wchar_t  kProcessName[]  = L"target.exe";
        constexpr wchar_t  kModuleName[]   = L"target.exe"; // or e.g. L"engine.dll"
        constexpr uintptr_t kDirectOffset  = 0x00AB1234;    // module-relative flat read

        const std::array<uintptr_t, 3> kChain = {
            0x00C01000,  // module_base + this → ptr0
            0x00000060,  // ptr0 + this         → ptr1
            0x00000018,  // ptr1 + this         → final uint64
        };
        // ─────────────────────────────────────────────────────────────────────

        const DWORD     pid  = get_process_id(kProcessName);
        const HANDLE    proc = open_process(pid);
        const uintptr_t mod  = get_module_base(proc, kModuleName);

        const uint64_t direct  = read_at_module_offset(proc, mod, kDirectOffset);
        const uint64_t chained = resolve_ptr_chain(proc, mod, kChain);

        printf("PID          : %lu\n",   static_cast<unsigned long>(pid));
        printf("Module base  : 0x%llX\n", static_cast<unsigned long long>(mod));
        printf("Direct read  : 0x%016llX\n", static_cast<unsigned long long>(direct));
        printf("Chain result : 0x%016llX\n", static_cast<unsigned long long>(chained));

        CloseHandle(proc);
    }
    catch (const std::exception& e)
    {
        fprintf(stderr, "error: %s\n", e.what());
        return 1;
    }

    return 0;
}

// proj.cpp — world-to-screen projection and world-to-radar transform
//
// Provides:
//   1. world_to_screen  — projects a 3D world position to 2D screen coords
//                         using a column-major 4x4 view-projection matrix.
//   2. world_to_radar   — maps a world position and local yaw angle to a 2D
//                         radar blip position within a circular minimap.
//
// C++17 | no external dependencies | header-only-friendly layout
//
// Build (MSVC):   cl /std:c++17 /O2 proj.cpp
// Build (GCC/Clang): g++ -std=c++17 -O2 proj.cpp -o proj

#include <array>
#include <cmath>
#include <cstdio>
#include <optional>

// ─── math primitives ─────────────────────────────────────────────────────────

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };
struct Vec4 { float x, y, z, w; };

// Column-major 4x4 matrix: m[col][row], matching HLSL/GLSL convention.
// m[0] = col 0 = { m00, m10, m20, m30 }
using Mat4 = std::array<std::array<float, 4>, 4>;

// Multiply a 4-component column vector by a column-major 4x4 matrix.
static Vec4 mat4_mul_vec4(const Mat4& m, Vec4 v)
{
    return {
        m[0][0]*v.x + m[1][0]*v.y + m[2][0]*v.z + m[3][0]*v.w,
        m[0][1]*v.x + m[1][1]*v.y + m[2][1]*v.z + m[3][1]*v.w,
        m[0][2]*v.x + m[1][2]*v.y + m[2][2]*v.z + m[3][2]*v.w,
        m[0][3]*v.x + m[1][3]*v.y + m[2][3]*v.z + m[3][3]*v.w,
    };
}

// ─── 1. world_to_screen ───────────────────────────────────────────────────────
//
// Projects `world_pos` through the combined view-projection matrix `vp` and
// maps the resulting NDC coordinate to screen pixels.
//
// vp           Column-major view-projection matrix (view * projection, or
//              however the game builds it — supply whatever MVP excludes the
//              model transform when the entity is already in world space).
// world_pos    3D world-space position to project.
// screen_w     Viewport width in pixels.
// screen_h     Viewport height in pixels.
//
// Returns the screen-space pixel coordinate, or std::nullopt when the point
// is behind the near plane (w <= 0) or beyond the far plane.
std::optional<Vec2> world_to_screen(
    const Mat4& vp,
    Vec3        world_pos,
    float       screen_w,
    float       screen_h)
{
    // Transform to clip space.
    const Vec4 clip = mat4_mul_vec4(vp, { world_pos.x, world_pos.y, world_pos.z, 1.0f });

    // Reject points behind the camera; a small epsilon avoids divide-by-zero
    // at the exact near plane.
    if (clip.w <= 1e-5f)
        return std::nullopt;

    // Perspective divide → NDC in [-1, 1].
    const float inv_w = 1.0f / clip.w;
    const float ndc_x = clip.x * inv_w;
    const float ndc_y = clip.y * inv_w;

    // Optionally reject points that project outside the viewport frustum.
    // Comment this block out if you want off-screen positions (e.g. for clamped
    // ESP arrows) rather than a hard reject.
    if (ndc_x < -1.0f || ndc_x > 1.0f ||
        ndc_y < -1.0f || ndc_y > 1.0f)
        return std::nullopt;

    // NDC → screen pixels.
    // NDC (-1,+1) maps to (0,screen_w) on X, and (+1,-1) on Y (Y flipped).
    return Vec2{
        (ndc_x + 1.0f) * 0.5f * screen_w,
        (1.0f - ndc_y) * 0.5f * screen_h,
    };
}

// ─── 2. world_to_radar ───────────────────────────────────────────────────────
//
// Maps a target world position to a 2D radar blip position, rotating the world
// so the local player always faces "up" on the minimap.
//
// local_pos    World position of the local player (the minimap centre).
// target_pos   World position of the entity we want a blip for.
// local_yaw    Yaw of the local player in RADIANS, clockwise from +Z forward
//              (adjust the rotation sign below if your engine uses a different
//              convention — Unreal and Source both have quirks here).
// radar_radius Radius of the radar circle in screen pixels.  The returned
//              position is clamped to this circle when `clamp_to_edge` is true.
// scale        World units per radar pixel.  E.g. 100.0f means 100 units of
//              world space fits in one pixel of the radar.
// clamp_to_edge If true, blips that fall outside the radar disk are moved to
//              its circumference so they remain visible as edge indicators.
//
// Returns a Vec2 relative to the radar centre (0,0).  Add the screen-space
// radar centre position to get the final draw coordinate.
Vec2 world_to_radar(
    Vec3  local_pos,
    Vec3  target_pos,
    float local_yaw,
    float radar_radius,
    float scale,
    bool  clamp_to_edge)
{
    // Delta from local player to target in world space (XZ plane; ignore Y/Z
    // height unless your game is fully 3-D on the radar too).
    const float dx = target_pos.x - local_pos.x;
    const float dz = target_pos.z - local_pos.z;

    // Rotate the delta by -local_yaw so that the player's forward direction
    // becomes "up" (negative screen Y) on the minimap.
    //
    // For a clockwise-from-+Z yaw convention:
    //   radar_x = dx * cos(-yaw) - dz * sin(-yaw)
    //   radar_y = dx * sin(-yaw) + dz * cos(-yaw)   (screen Y, up = negative)
    const float cos_yaw = std::cos(-local_yaw);
    const float sin_yaw = std::sin(-local_yaw);

    float rx = ( dx * cos_yaw - dz * sin_yaw) / scale;
    float ry = (-dx * sin_yaw - dz * cos_yaw) / scale;  // flip Z so +world-Z = up

    // Clamp to radar circle.
    if (clamp_to_edge)
    {
        const float dist = std::sqrt(rx * rx + ry * ry);
        if (dist > radar_radius && dist > 1e-6f)
        {
            const float inv_dist = radar_radius / dist;
            rx *= inv_dist;
            ry *= inv_dist;
        }
    }

    return { rx, ry };
}

// ─── demo / smoke-test ────────────────────────────────────────────────────────

int main()
{
    // Build a simple orthographic-style view-projection for testing.
    // In a real game you'd rip this matrix straight from the renderer.
    //
    // We construct a minimal perspective matrix here:
    //   fov = 90 degrees, aspect = 16/9, near = 0.1, far = 1000
    constexpr float fov    = 1.5707963f; // pi/2 = 90 degrees
    constexpr float aspect = 16.0f / 9.0f;
    constexpr float near_z = 0.1f;
    constexpr float far_z  = 1000.0f;

    const float f      = 1.0f / std::tan(fov * 0.5f);
    const float range  = 1.0f / (near_z - far_z);

    // Column-major OpenGL-convention perspective (right-handed, NDC z in [-1,1]).
    // Replace with the game's actual matrix — this is only here so the demo
    // compiles and produces sensible numbers without a renderer.
    Mat4 proj{};
    proj[0][0] = f / aspect;
    proj[1][1] = f;
    proj[2][2] = (far_z + near_z) * range;
    proj[2][3] = -1.0f;
    proj[3][2] = 2.0f * far_z * near_z * range;

    // Trivial identity view — camera at origin looking down -Z.
    Mat4 view{};
    view[0][0] = view[1][1] = view[2][2] = view[3][3] = 1.0f;

    // VP = view * proj (identity view here, so VP == proj).
    // For a real game you'd read the VP matrix from memory directly.
    Mat4 vp = proj; // simplified; in practice: multiply view * proj

    constexpr float W = 1920.0f;
    constexpr float H = 1080.0f;

    // ── world_to_screen ───────────────────────────────────────────────────────
    const Vec3 target_ws = { 0.0f, 0.0f, -10.0f }; // 10 units in front
    const auto screen_pt = world_to_screen(vp, target_ws, W, H);

    if (screen_pt)
        printf("[w2s] world (%.1f, %.1f, %.1f) → screen (%.1f, %.1f)\n",
               target_ws.x, target_ws.y, target_ws.z,
               screen_pt->x, screen_pt->y);
    else
        printf("[w2s] point is behind the camera or off-screen\n");

    // ── world_to_radar ────────────────────────────────────────────────────────
    const Vec3  local_pos  = { 0.0f, 0.0f, 0.0f };
    const Vec3  enemy_pos  = { 50.0f, 0.0f, 50.0f }; // 50 units ahead-right
    const float local_yaw  = 0.0f;                    // facing +Z
    const float radar_r    = 64.0f;                   // 64 px radius minimap
    const float world_scale = 2.0f;                   // 2 world units per pixel

    const Vec2 blip = world_to_radar(
        local_pos, enemy_pos, local_yaw, radar_r, world_scale, true);

    printf("[radar] enemy blip relative to centre: (%.2f, %.2f) px\n",
           blip.x, blip.y);

    return 0;
}
